import{_ as a,o as t,c as n,a5 as r}from"./chunks/framework.pJebtgMf.js";const d=JSON.parse('{"title":"AI 动态 · 2026-08-22","description":"","frontmatter":{"title":"AI 动态 · 2026-08-22","date":"2026-08-22T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-08/ai-news-2026-08-22.md","filePath":"news/2026-08/ai-news-2026-08-22.md","lastUpdated":null}'),s={name:"news/2026-08/ai-news-2026-08-22.md"};function i(l,e,o,p,c,h){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="ai-动态-·-2026-08-22" tabindex="-1">AI 动态 · 2026-08-22 <a class="header-anchor" href="#ai-动态-·-2026-08-22" aria-label="Permalink to &quot;AI 动态 · 2026-08-22&quot;">​</a></h1><blockquote><p>截至 2026-08-22。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="anthropic-的-opus-4-6-被曝可轻易绕过安全限制生成色情内容" tabindex="-1">Anthropic 的 Opus 4.6 被曝可轻易绕过安全限制生成色情内容 <a class="header-anchor" href="#anthropic-的-opus-4-6-被曝可轻易绕过安全限制生成色情内容" aria-label="Permalink to &quot;Anthropic 的 Opus 4.6 被曝可轻易绕过安全限制生成色情内容&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-22">2026-08-22</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/959f65199293.jpg" alt="配图"></p><p>TechCrunch 测试发现，Anthropic 最新模型 Claude Opus 4.6 在 10 次直接请求中全部立即生成了明确色情内容，无需复杂提示即可绕过其使用政策中禁止生成性相关内容的规定。旧型号如 Opus 3 和 Haiku 4.5 也存在类似漏洞。对读者：在部署强模型时，默认安全护栏可能失效，需自行增加内容过滤层。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/21/anthropics-opus-4-6-is-a-smut-machine/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="英伟达投资数据中心开发商-cloverleaf-infrastructure" tabindex="-1">英伟达投资数据中心开发商 Cloverleaf Infrastructure <a class="header-anchor" href="#英伟达投资数据中心开发商-cloverleaf-infrastructure" aria-label="Permalink to &quot;英伟达投资数据中心开发商 Cloverleaf Infrastructure&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-22">2026-08-22</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/61f2570a414a.jpg" alt="配图"></p><p>英伟达宣布与数据中心基础设施开发商 Cloverleaf Infrastructure 建立合作伙伴关系，据华尔街日报报道投资额或达数亿美元，英伟达将持有少数股权。Cloverleaf 成立于 2024 年，充当公用事业公司与数据中心之间的中间人，提供电力等关键基础设施。对读者：英伟达正从芯片向算力基础设施全链条渗透，相关生态合作值得关注。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/21/nvidia-partners-with-data-center-developer-cloverleaf/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="英伟达研究-ai-agent-的-套件-比模型本身更重要" tabindex="-1">英伟达研究：AI Agent 的“套件”比模型本身更重要 <a class="header-anchor" href="#英伟达研究-ai-agent-的-套件-比模型本身更重要" aria-label="Permalink to &quot;英伟达研究：AI Agent 的“套件”比模型本身更重要&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-22">2026-08-22</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/387feab9f230.jpg" alt="配图"></p><p>英伟达发布新研究，指出在长周期任务中，围绕模型构建的“套件”（harness）——包括工具、内存管理和规则——比底层模型更关键。通过定制套件和“监督者”组件，Claude Opus 5 在 ARC-AGI-3 基准上取得 100% 分数。对读者：构建 Agent 时，应优先投入工程化套件设计，而非仅追求更强模型。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/21/nvidia-just-showed-that-the-harness-not-the-ai-model-is-now-the-real-hero/" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="runlayer-与-rippling-互撤诉讼-rippling-随即发布竞品" tabindex="-1">Runlayer 与 Rippling 互撤诉讼，Rippling 随即发布竞品 <a class="header-anchor" href="#runlayer-与-rippling-互撤诉讼-rippling-随即发布竞品" aria-label="Permalink to &quot;Runlayer 与 Rippling 互撤诉讼，Rippling 随即发布竞品&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-22">2026-08-22</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/98222b821755.jpg" alt="配图"></p><p>Runlayer 和 Rippling 已互相撤销诉讼，未支付任何赔偿。Rippling 随即发布了争议核心的 MCP 网关产品，与 Runlayer 直接竞争。这场短暂的法律纠纷为创始人敲响警钟：在 AI 时代，下一个竞争对手可能是潜在客户。对读者：创业公司需警惕大客户转身成为竞品，尽早建立护城河。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/20/runlayer-rippling-drop-lawsuits-but-the-brouhaha-is-still-a-cautionary-tale-for-founders/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><h3 id="超百万人点击-linkedin-的-疑似-ai-生成-举报按钮" tabindex="-1">超百万人点击 LinkedIn 的“疑似 AI 生成”举报按钮 <a class="header-anchor" href="#超百万人点击-linkedin-的-疑似-ai-生成-举报按钮" aria-label="Permalink to &quot;超百万人点击 LinkedIn 的“疑似 AI 生成”举报按钮&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">The Verge AI</span><time datetime="2026-08-22">2026-08-22</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/b85666e2b786.jpg" alt="配图"></p><p>LinkedIn 于 7 月 30 日推出的“Seems like AI slop”按钮已获超百万人使用。该按钮位于帖子三点菜单中，用户可标记疑似 AI 生成内容。此前 AI 检测工具 Pangram 发现 LinkedIn 41% 的长文帖子被标记为完全 AI 生成。LinkedIn 同时升级了内容分类器。对读者：平台治理 AI 内容已成刚需，内容创作者需注意 AI 生成内容的标识与质量。</p><p class="news-entry-source"><a href="https://www.theverge.com/ai-artificial-intelligence/983502/linkedin-ai-slop-button-one-million-people-message" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="google-推出-首选来源-按钮-帮助出版商对抗-ai-流量下滑" tabindex="-1">Google 推出“首选来源”按钮，帮助出版商对抗 AI 流量下滑 <a class="header-anchor" href="#google-推出-首选来源-按钮-帮助出版商对抗-ai-流量下滑" aria-label="Permalink to &quot;Google 推出“首选来源”按钮，帮助出版商对抗 AI 流量下滑&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">TechCrunch AI</span><time datetime="2026-08-22">2026-08-22</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/8e3fc9de3be5.jpg" alt="配图"></p><p>Google 向出版商提供新的“首选来源”按钮，读者点击后可在 Search、Discover 和 Google News 中更频繁看到该来源内容。该功能此前已在 AI Mode 和 AI Overviews 中推出，现扩展至全部搜索产品。此举旨在缓解 AI 搜索减少网页点击对出版商的冲击。对读者：内容站点应尽快集成该按钮，争取在 AI 搜索时代保留用户触达。</p><p class="news-entry-source"><a href="https://techcrunch.com/2026/08/20/google-gives-publishers-a-new-way-to-fight-ai-driven-traffic-losses/" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="神秘模型-ox-alpha-突袭-openrouter-性能引全网猜测" tabindex="-1">神秘模型“Ox Alpha”突袭 OpenRouter，性能引全网猜测 <a class="header-anchor" href="#神秘模型-ox-alpha-突袭-openrouter-性能引全网猜测" aria-label="Permalink to &quot;神秘模型“Ox Alpha”突袭 OpenRouter，性能引全网猜测&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-22">2026-08-22</time></p><p>OpenRouter 以忍者表情匿名发布模型“Ox Alpha”，支持 100 万 Token 上下文、文本/图像/视频输入，定位高效编程与长时 Agent 任务。模型参数、架构和供应商均未公开，当前免费。社区猜测其来自 Google、小米或腾讯。支持工具调用和 JSON 输出，但不支持严格 JSON Schema。对读者：匿名模型免费可用，但生产环境需谨慎评估其真实身份与稳定性。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/3MNJh5F34GSsRQJJWJzY?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="deepseek-发布多模态模型-deepseek-v4-flash-vision-exp" tabindex="-1">DeepSeek 发布多模态模型 deepseek-v4-flash-vision-exp <a class="header-anchor" href="#deepseek-发布多模态模型-deepseek-v4-flash-vision-exp" aria-label="Permalink to &quot;DeepSeek 发布多模态模型 deepseek-v4-flash-vision-exp&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-22">2026-08-22</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/dafd4949450f.png" alt="配图"></p><p>DeepSeek 通过官方 API 上线实验模型 deepseek-v4-flash-vision-exp，首次开放 V4 系列视觉理解能力。图片转 token 计费，单图上限 384 tokens，定价与 V4-Flash 一致。支持 Chat Completions、Messages、Responses 三种接口和三种图片传入方式。多数指标高于 V4-Flash-0731，尤其在工具调用和长周期 Agent 任务上提升明显。对读者：多模态 Agent 开发可低成本接入，注意实验模型稳定性。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/jlTfe57D4r0Juzpz8Fk5?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="sub2api-开源中转服务统一接入多模型订阅" tabindex="-1">Sub2API：开源中转服务统一接入多模型订阅 <a class="header-anchor" href="#sub2api-开源中转服务统一接入多模型订阅" aria-label="Permalink to &quot;Sub2API：开源中转服务统一接入多模型订阅&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Wei-Shaw/sub2api</span><time datetime="2026-08-22">2026-08-22</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/a339a8a292ad.png" alt="配图"></p><p>Sub2API 是一个一站式开源中转服务，让 Claude、OpenAI、Gemini、Grok 等订阅统一接入，支持拼车共享以分摊成本，可在原生工具中无缝使用。该项目在 GitHub 上开源，为开发者提供多模型统一 API 入口。对读者：多模型订阅用户可考虑自建中转层，降低 API 调用成本。</p><p class="news-entry-source"><a href="https://github.com/Wei-Shaw/sub2api" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="腾讯开源-ai-红队平台-ai-infra-guard" tabindex="-1">腾讯开源 AI 红队平台 AI-Infra-Guard <a class="header-anchor" href="#腾讯开源-ai-红队平台-ai-infra-guard" aria-label="Permalink to &quot;腾讯开源 AI 红队平台 AI-Infra-Guard&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">Tencent/AI-Infra-Guard</span><time datetime="2026-08-22">2026-08-22</time></p><p><img src="https://img.penn-notes.draftly.cn/news/2026-08/6e4abcd636d5.png" alt="配图"></p><p>腾讯发布 AI-Infra-Guard，一个全栈 AI 红队测试平台，通过 Agent 扫描、技能扫描、MCP 扫描、AI 基础设施扫描和 LLM 越狱评估来保障 AI 生态系统安全。该项目在 GitHub 上开源，为 AI 安全测试提供系统化工具。对读者：AI 应用安全测试可引入该平台，覆盖 Agent 与 MCP 等新兴攻击面。</p><p class="news-entry-source"><a href="https://github.com/Tencent/AI-Infra-Guard" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="cloudflare-推出-agent-tracing-统一观测-ai-agent-会话" tabindex="-1">Cloudflare 推出 Agent Tracing，统一观测 AI Agent 会话 <a class="header-anchor" href="#cloudflare-推出-agent-tracing-统一观测-ai-agent-会话" aria-label="Permalink to &quot;Cloudflare 推出 Agent Tracing，统一观测 AI Agent 会话&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-22">2026-08-22</time></p><p>Cloudflare 发布 Cloudflare Agents 首个组件 Agent Tracing，提供集中查看已部署 Agent 会话的统一 Dashboard。该功能在 Workers Tracing 基础上增加 Agent 级 Span，可追踪模型调用、工具执行和审批等，并附带 Token 使用量。Beta 期间免费，2026 年 10 月 1 日起纳入 Workers Observability 计费。对读者：Agent 调试将告别黑盒，建议提前规划可观测性接入。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/IBYDTeu3rse9tH3549wf?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="npm-12-默认封杀-postinstall-脚本-转向显式信任模型" tabindex="-1">npm 12 默认封杀 postinstall 脚本，转向显式信任模型 <a class="header-anchor" href="#npm-12-默认封杀-postinstall-脚本-转向显式信任模型" aria-label="Permalink to &quot;npm 12 默认封杀 postinstall 脚本，转向显式信任模型&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-08-22">2026-08-22</time></p><p>npm 12 发布，将 allowScripts 默认关闭，依赖项的 preinstall、install 和 postinstall 脚本不再自动运行，需开发者明确批准。同时 --allow-git 和 --allow-remote 默认设为 none，阻断 Git 依赖和 HTTPS tarball 的代码执行路径。社区反应总体支持，但也有对审批疲劳和 patch-package 等合法用途的担忧。对读者：升级后需审查依赖脚本并配置允许列表，注意与 ignore-scripts 的优先级冲突。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/fPGPEF2hwCKtz3PTg69C?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><p>（本日无新条目）</p></div>',8)])])}const m=a(s,[["render",i]]);export{d as __pageData,m as default};
